(4350885, 627241, 88010, '<td valign="top">nice light, nice subject.</td>', 'nice light, nice subject.', '2008-01-01 17:58:00.000000', NULL, 1),
(4350886, 626797, 81530, '<td valign="top">Lovely pattern and reflections. Very nice photograph.</td>', 'Lovely pattern and reflections. Very nice photograph.', '2008-01-01 17:58:31.000000', NULL, 1),
