(4351065, 627974, 81530, '<td valign="top">Nice framing with the tree branch.</td>', 'Nice framing with the tree branch.', '2008-01-01 18:44:25.000000', NULL, 1),
(4351067, 624477, 81530, '<td valign="top">I''d like to see a little more separation from the white shirt and the white background.</td>', 'I''d like to see a little more separation from the white shirt and the white background.', '2008-01-01 18:45:08.000000', NULL, 1),
(4351070, 627710, 77543, '<td valign="top">I''d straighten this so the base is level.</td>', 'I''d straighten this so the base is level.', '2008-01-01 18:45:38.000000', NULL, 1),
