INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4352783, 626327, 7786, '<td valign="top">One of the best in this compedition. The simplicity of its composition and colors are a good match. Well done.</td>', 'One of the best in this compedition. The simplicity of its composition and colors are a good match. Well done.', '2008-01-02 05:08:09.000000', NULL, 1),
