(4357937, 624387, 37845, '<td valign="top">The depth of focus is too shallow for this shot. Also, the shalow focus would have been better if the focus were on the head of the dog.</td>', 'The depth of focus is too shallow for this shot. Also, the shalow focus would have been better if the focus were on the head of the dog.', '2008-01-03 15:48:06.000000', NULL, 1),
(4357939, 627315, 77192, '<td valign="top">love the soft colours</td>', 'love the soft colours', '2008-01-03 15:48:37.000000', NULL, 1),
(4357940, 624959, 77192, '<td valign="top">nice pose and relaxed expression</td>', 'nice pose and relaxed expression', '2008-01-03 15:48:51.000000', NULL, 1),
(4357958, 625955, 42495, '<td valign="top">I think this has a lot of potential, but I find the OOF branches in front a bit distracting.</td>', 'I think this has a lot of potential, but I find the OOF branches in front a bit distracting.', '2008-01-03 16:01:40.000000', NULL, 1),
(4357972, 627111, 37845, '<td valign="top">Stunning image. Certainly a place I would like to visit someday.</td>', 'Stunning image. Certainly a place I would like to visit someday.', '2008-01-03 16:08:17.000000', NULL, 1),
(4357977, 626958, 37845, '<td valign="top">Incredible shot. Love the snow on the trees, and the blue sky is outstanding.</td>', 'Incredible shot. Love the snow on the trees, and the blue sky is outstanding.', '2008-01-03 16:10:18.000000', NULL, 1),
(4357979, 624382, 37845, '<td valign="top">This shot is very grainy. Not sure if it was intentional. If it wasnt, try reducing the ISO on your camera to reduce the noise.</td>', 'This shot is very grainy. Not sure if it was intentional. If it wasnt, try reducing the ISO on your camera to reduce the noise.', '2008-01-03 16:10:53.000000', NULL, 1),
(4357994, 627664, 37845, '<td valign="top">I cant make out what is distorting the image in the center. Also, the out of focus branches in the foreground are a bit of a distraction to me.</td>', 'I cant make out what is distorting the image in the center. Also, the out of focus branches in the foreground are a bit of a distraction to me.', '2008-01-03 16:18:31.000000', NULL, 1),
(4357997, 626056, 37845, '<td valign="top">Quite the look too. Very cute.</td>', 'Quite the look too. Very cute.', '2008-01-03 16:19:27.000000', NULL, 1),
(4358011, 627527, 37845, '<td valign="top">Cool reflection. The water must have been extremely still, the top half of the photo looks like the real thing.</td>', 'Cool reflection. The water must have been extremely still, the top half of the photo looks like the real thing.', '2008-01-03 16:24:34.000000', NULL, 1),
