(4358049, 627734, 35994, '<td valign="top">Great macro eye shot! I like the b&amp;w.</td>', 'Great macro eye shot! I like the b&w.', '2008-01-03 16:39:40.000000', NULL, 1),
(4358053, 626872, 37845, '<td valign="top">I like the high contrast black and white here. Nicely done.</td>', 'I like the high contrast black and white here. Nicely done.', '2008-01-03 16:40:24.000000', NULL, 1),
(4358063, 626466, 65234, '<td valign="top">Nice diagonals in the composition and very good detail on the conure.</td>', 'Nice diagonals in the composition and very good detail on the conure.', '2008-01-03 16:43:36.000000', NULL, 1),
