(4367602, 626821, 28882, '<td valign="top">very nice indeed.</td>', 'very nice indeed.', '2008-01-06 22:01:46.000000', NULL, 1),
(4367607, 625061, 28882, '<td valign="top">nice sharp image.  love the soft background.  i see a little burning in the green around the top beak, not too bad though.  overall i like this.</td>', 'nice sharp image.  love the soft background.  i see a little burning in the green around the top beak, not too bad though.  overall i like this.', '2008-01-06 22:03:24.000000', NULL, 1),
