(4372828, 626327, 42013, '<td valign="top">Classic midwest. You were one of my top 3 and glad to see it ribbon. Congrats! Your username is cool too. ;)</td>', 'Classic midwest. You were one of my top 3 and glad to see it ribbon. Congrats! Your username is cool too. ;)', '2008-01-08 01:39:48.000000', NULL, 0),
(4372832, 625638, 65035, '<td valign="top">Wooot! Go Rob! Congratulations on an awesome photo, huge score and 7th in free study.</td>', 'Wooot! Go Rob! Congratulations on an awesome photo, huge score and 7th in free study.', '2008-01-08 01:40:48.000000', NULL, 0),
(4372833, 623247, 66398, '<td valign="top">Very beautiful little girl you have there and a shot to be proud of and to hang on the wall. Not a bad finish either.</td>', 'Very beautiful little girl you have there and a shot to be proud of and to hang on the wall. Not a bad finish either.', '2008-01-08 01:41:27.000000', NULL, 0),
(4372836, 620358, 80459, '<td valign="top">Congratulations!!! Wonderful!!! Trolls stink!!!</td>', 'Congratulations!!! Wonderful!!! Trolls stink!!!', '2008-01-08 01:42:06.000000', NULL, 0),
