(4372861, 627704, 70514, '<td valign="top">I love the low key effect. Nice use of processing for this image.  I really like this.</td>', 'I love the low key effect. Nice use of processing for this image.  I really like this.', '2008-01-08 01:53:05.000000', NULL, 0),
(4372863, 626660, 33352, '<td valign="top">Underated finish, very good processing on this strong finish.</td>', 'Underated finish, very good processing on this strong finish.', '2008-01-08 01:54:38.000000', NULL, 0),
(4372864, 627915, 30791, '<td valign="top">now some of these photos  i dont remember voting on, this being one of them. i think im voting in my sleep sometimes. but now im looking through the results and i wonder why i gave this ia 5</td>', 'now some of these photos  i dont remember voting on, this being one of them. i think im voting in my sleep sometimes. but now im looking through the results and i wonder why i gave this ia 5', '2008-01-08 01:55:20.000000', NULL, 0),
