(4375946, 622456, 15305, '<td valign="top">I love nature shots and I know how hard it is to get sharp shots like this one, however the lack of head is the key factor that affected it.</td>', 'I love nature shots and I know how hard it is to get sharp shots like this one, however the lack of head is the key factor that affected it.', '2008-01-08 23:40:06.000000', NULL, 0),
(4375956, 623985, 62318, '<td valign="top">Very cute post and a nice high contrast treatment. Not much I would change.</td>', 'Very cute post and a nice high contrast treatment. Not much I would change.', '2008-01-08 23:43:42.000000', NULL, 0),
(4375958, 627999, 15305, '<td valign="top">I love simple and artsy shots like yours. Your created a great mood in the scene, however I find the harsh light on the wall to be distracting.</td>', 'I love simple and artsy shots like yours. Your created a great mood in the scene, however I find the harsh light on the wall to be distracting.', '2008-01-08 23:44:25.000000', NULL, 0),
(4375962, 626660, 58691, '<td valign="top">Shez, this shot is just outstanding.</td>', 'Shez, this shot is just outstanding.', '2008-01-08 23:44:49.000000', NULL, 0),
