(4376241, 627981, 11078, '<td valign="top">stunning image</td>', 'stunning image', '2008-01-09 00:50:31.000000', NULL, 0),
(4376261, 626483, 15305, '<td valign="top">Great shot, strong leading lines, good contrast, nice mood.</td>', 'Great shot, strong leading lines, good contrast, nice mood.', '2008-01-09 00:53:32.000000', NULL, 0),
(4376293, 624387, 15305, '<td valign="top">Just one of those artsy images that doesn''t fit DPC taste.</td>', 'Just one of those artsy images that doesn''t fit DPC taste.', '2008-01-09 01:00:20.000000', NULL, 0),
(4376306, 626611, 15305, '<td valign="top">Great shot! I love the tilted horizon creating leading lines with lots of details, contrast and color.</td>', 'Great shot! I love the tilted horizon creating leading lines with lots of details, contrast and color.', '2008-01-09 01:04:27.000000', NULL, 0),
(4376354, 627981, 18505, '<td valign="top">Beautiful!!  Awesome textures!</td>', 'Beautiful!!  Awesome textures!', '2008-01-09 01:22:09.000000', NULL, 0),
